import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
  DirectionalLight,
  Color,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'journal-thumbnail-card';

  // ---- dimensions ----
  const cardWidth = 2.0;
  const imageHeight = 1.25;
  const captionHeight = 0.35;
  const gap = 0.02;
  const cardHeight = imageHeight + captionHeight + gap;

  // ---- drop shadow / depth separation plane ----
  const shadowGeo = new PlaneGeometry(cardWidth + 0.24, cardHeight + 0.24);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 0.45,
  });
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0.04, -0.05, -0.05);
  root.add(shadowPlane);

  // ---- machined-metal bezel frame ----
  const frameGeo = new BoxGeometry(cardWidth + 0.08, cardHeight + 0.08, 0.06);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.45,
    roughness: 0.55,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.03);
  root.add(frame);

  // ---- image plane ----
  const imageGeo = new PlaneGeometry(cardWidth - 0.1, imageHeight);
  const imageMat = new MeshBasicNodeMaterial({ color: new Color(0x1a1a1f) });
  const imagePlane = new Mesh(imageGeo, imageMat);
  const imageY = cardHeight / 2 - imageHeight / 2;
  imagePlane.position.set(0, imageY, 0.01);
  root.add(imagePlane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageMat.map = tex;
      imageMat.color.set(0xffffff);
      imageMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- caption strip ----
  const captionGeo = new BoxGeometry(cardWidth - 0.06, captionHeight - 0.04, 0.05);
  const captionMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.surface),
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.1,
  });
  const captionStrip = new Mesh(captionGeo, captionMat);
  const captionY = -cardHeight / 2 + captionHeight / 2;
  captionStrip.position.set(0, captionY, 0.015);
  root.add(captionStrip);

  // ---- accent focus edge (thin underline, animated) ----
  const accentGeo = new BoxGeometry(cardWidth - 0.06, 0.018, 0.02);
  const accentMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.3,
    metalness: 0.2,
    roughness: 0.4,
  });
  const accentEdge = new Mesh(accentGeo, accentMat);
  accentEdge.position.set(0, -cardHeight / 2 + 0.02, 0.03);
  root.add(accentEdge);

  // ---- rim light (accent hue, node-local) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.5, -1.0, 1.5);
  root.add(rimLight);

  // ---- interaction state ----
  let hovering = false;
  const baseY = 0;
  const baseScale = 1;

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(root.position, { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(root.rotation, { x: -0.05, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(accentMat, { emissiveIntensity: 2.0, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(frame.scale, { x: 1.01, y: 1.01, duration: 0.3, ease: 'power2.out' }, 0);

  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );

  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
  pressTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.18, ease: 'power2.out' });

  function onPointerOver() {
    if (hovering) return;
    hovering = true;
    hoverTl.play();
  }
  function onPointerOut() {
    if (!hovering) return;
    hovering = false;
    hoverTl.reverse();
  }
  function onPointerDown() {
    pressTl.restart();
  }
  function onPointerUp() {}
  function onClick() {
    pressTl.restart();
    ctx.emit('hub-journal.select', {
      nodeId: config.id ?? 'hub-journal-card',
      to: 'hub-journal',
    });
  }
  function onFocus() {
    gsap.to(accentMat, { emissiveIntensity: 2.2, duration: 0.2, ease: 'power2.out' });
  }
  function onBlur() {
    gsap.to(accentMat, { emissiveIntensity: 0.3, duration: 0.2, ease: 'power2.out' });
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerEnter: onPointerOver,
    onHoverStart: onPointerOver,
    onPointerOut,
    onPointerLeave: onPointerOut,
    onHoverEnd: onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
    onFocus,
    onBlur,
  };

  // ---- entrance ----
  root.position.y = baseY - 0.2;
  const introTl = gsap.timeline();
  introTl.to(root.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
  settleTl.play();

  root.userData.cleanup = () => {
    hoverTl.kill();
    settleTl.kill();
    pressTl.kill();
    introTl.kill();

    shadowGeo.dispose();
    shadowMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    imageGeo.dispose();
    imageMat.map?.dispose?.();
    imageMat.dispose();
    captionGeo.dispose();
    captionMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();

    root.remove(rimLight);
    rimLight.dispose?.();
  };

  return root;
}
